/**
 * The first call the portal makes. Returns the home (for branding and
the urgent number), the person who died, the service details, what is
outstanding, and the contact the link identifies. A revoked, expired
or unknown token is a 401 here and the portal shows the "ask the home
for a new link" screen.

 * @summary Who this link belongs to, and everything needed to draw the portal
 */
export const GetFamilySessionResponse = zod
  .object({
    contact: zod.object({
      id: zod.number(),
      caseId: zod.number(),
      name: zod.string(),
      relationship: zod.string().nullable(),
      phone: zod.string().nullable(),
      email: zod.string().nullable(),
      role: zod.enum(["next_of_kin", "contributor"]),
      canInvite: zod.boolean(),
      expiresAt: zod.date(),
      revokedAt: zod.date().nullable(),
      firstSeenAt: zod.date().nullable(),
      lastSeenAt: zod.date().nullable(),
      createdAt: zod.date(),
    }),
    home: zod
      .object({
        name: zod.string(),
        slug: zod.string(),
        accentColor: zod.string(),
        logoUploadId: zod.number().nullable(),
        phone: zod.string().nullable(),
        urgentPhone: zod.string().nullable(),
        officeOpensMinute: zod.number(),
        officeClosesMinute: zod.number(),
        timezone: zod.string(),
      })
      .describe(
        "The home as a family may see it - branding and how to reach it.",
      ),
    case: zod.object({
      id: zod.number(),
      decedentFirstName: zod.string(),
      decedentLastName: zod.string(),
      decedentPreferredName: zod.string().nullable(),
      displayName: zod.string(),
      dateOfBirth: zod.date().nullable(),
      dateOfDeath: zod.date().nullable(),
      portraitPhotoId: zod.number().nullable(),
      serviceAt: zod.date().nullable(),
      serviceLocation: zod.string().nullable(),
      serviceNotes: zod.string().nullable(),
      leadDirectorId: zod.number().nullable(),
      status: zod.enum(["intake", "active", "closed"]),
      closedAt: zod.date().nullable(),
      messagesLockAt: zod.date().nullable(),
      createdAt: zod.date(),
    }),
    leadDirector: zod.union([
      zod
        .object({
          displayName: zod.string().nullable(),
          title: zod.string().nullable(),
        })
        .describe("A staff member as a family sees them - a name and a title."),
      zod.null(),
    ]),
    photoCount: zod.number(),
    photoLimit: zod.number(),
    obituaryStatus: zod.enum(["family_draft", "submitted", "approved"]),
    outstandingDeadlines: zod.number(),
    unreadMessages: zod.number(),
    messagesLocked: zod.boolean(),
    aftercare: zod.union([
      zod.object({
        id: zod.number(),
        caseId: zod.number(),
        contactId: zod.number(),
        contactName: zod.string().nullable(),
        email: zod.string().nullable(),
        phone: zod.string().nullable(),
        brandedAs: zod.string(),
        status: zod.enum(["pending", "active", "done"]),
        startsAt: zod.date(),
        consentedAt: zod.date().nullable(),
        unsubscribedAt: zod.date().nullable(),
        deliveries: zod.array(
          zod.object({
            id: zod.number(),
            dayOffset: zod.number(),
            dueAt: zod.date(),
            sentAt: zod.date().nullable(),
            failedAt: zod.date().nullable(),
          }),
        ),
      }),
      zod.null(),
    ]),
  })
  .describe(
    "Everything the family portal needs on first load, in one call - the\nportal is opened on a phone, on mobile data, at a kitchen table, and\nfour round trips before anything renders is four chances to look\nbroken.\n",
  );

