/**
 * @summary The thread with the funeral home
 */
export const GetFamilyMessagesResponse = zod
  .object({
    messages: zod.array(
      zod.object({
        id: zod.number(),
        caseId: zod.number(),
        body: zod.string(),
        authorSide: zod
          .enum(["home", "family"])
          .describe(
            "Which side wrote it, derived on the server from which author\ncolumn is set rather than stored, so the two cannot disagree.\n",
          ),
        authorName: zod.string().nullable(),
        authorTitle: zod.string().nullable(),
        sentOutsideOfficeHours: zod.boolean(),
        readAt: zod.date().nullable(),
        createdAt: zod.date(),
      }),
    ),
    locked: zod.boolean(),
    lockedAt: zod.date().nullable(),
    withinOfficeHours: zod.boolean(),
    officeOpensMinute: zod.number(),
    officeClosesMinute: zod.number(),
    timezone: zod.string(),
    urgentPhone: zod.string().nullable(),
  })
  .describe(
    "The thread plus the state the UI needs to say something honest about\nit: whether it is locked, and whether a message written now would land\noutside office hours.\n",
  );

/**
 * Always delivered, whatever the hour. When it is sent outside the
home's office hours the response says so, so the portal can tell the
family plainly when it will be read and offer the 24-hour line - which
is a truthful thing to say, unlike holding the message back.

 * @summary Ask the director something
 */

export const PostFamilyMessageBody = zod.object({
  body: zod.string().min(1),
});

